package com.bank.product.service;

import com.bank.product.dto.ProductDtos.*; import com.bank.product.exception.*; import com.bank.product.model.*; import com.bank.product.repository.*;
import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import java.util.function.*;

@Service @RequiredArgsConstructor
public class ProductService {
 private final ProductRepository products; private final CustomerCategoryRepository categories; private final ProductMapper mapper;

 @Transactional public ProductResponse create(ProductRequest r,String user){ if(products.existsById(norm(r.productCode()))) throw new ConflictException("Product code already exists"); Product p=new Product(); apply(p,r,user); return mapper.response(products.findAggregate(p.getProductCode()).orElse(p)); }
 @Transactional public ProductResponse update(String code,ProductRequest r,String user){ Product p=find(code); if(!norm(code).equals(norm(r.productCode()))) throw new BadRequestException("productCode in path and body must match"); apply(p,r,user); products.saveAndFlush(p); return mapper.response(products.findAggregate(p.getProductCode()).orElseThrow()); }
 @Transactional(readOnly=true) public ProductResponse get(String code){return mapper.response(find(code));}
 @Transactional(readOnly=true) public List<ProductSummary> search(String type,LocalDate from,LocalDate to){return products.search(blank(type),from,to).stream().map(mapper::summary).toList();}
 @Transactional public ProductResponse status(String code,ProductStatus status,String approval,String user){Product p=find(code);p.setStatus(status);if(approval!=null)p.setApprovalStatus(approval);p.setAuditUserId(user);products.saveAndFlush(p);return mapper.response(find(code));}
 @Transactional(readOnly=true) public PricingResponse pricing(String code,String categoryCode,LocalDate asOf){ Product p=find(code); LocalDate d=asOf==null?LocalDate.now():asOf; List<ProductFeeRate> rows=p.getFeeRates().stream().filter(x->x.getCategory()==null||x.getCategory().getCategoryCode().equals(norm(categoryCode))).filter(x->!x.getEffectiveDate().isAfter(d)&&(x.getExpiryDate()==null||!x.getExpiryDate().isBefore(d))).toList(); BigDecimal add=rows.stream().map(ProductFeeRate::getAdditionalRatePercent).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add); BigDecimal penalty=rows.stream().map(ProductFeeRate::getPenaltyPercent).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::max); return new PricingResponse(p.getProductCode(),norm(categoryCode),p.getMinRate(),p.getMaxRate(),add,penalty,rows.stream().map(mapper::fee).toList()); }
 @Transactional public void delete(String code){Product p=find(code); if(p.getStatus()!=ProductStatus.UNDER_ESTABLISHMENT) throw new ConflictException("Only UNDER_ESTABLISHMENT products may be deleted; close live products through lifecycle status"); products.delete(p);}

 private Product find(String code){return products.findAggregate(norm(code)).orElseThrow(()->new NotFoundException("Product not found: "+code));}
 private void apply(Product p,ProductRequest r,String user){validate(r);p.setProductCode(norm(r.productCode()));p.setProductId(r.productId());p.setProductName(r.productName());p.setMarketName(r.marketName());p.setProductLine(r.productLine());p.setProductType(norm(r.productType()));p.setProductSubtype(r.productSubtype());p.setProductGroup(r.productGroup());p.setCurrency(norm(r.currency()));p.setMinTermMonths(r.minTermMonths());p.setMaxTermMonths(r.maxTermMonths());p.setMinRate(r.minRate());p.setMaxRate(r.maxRate());p.setEffectiveDate(r.effectiveDate());p.setExpiryDate(r.expiryDate());p.setStatus(r.status()==null?ProductStatus.UNDER_ESTABLISHMENT:r.status());p.setApprovalStatus(r.approvalStatus()==null?"DRAFT":norm(r.approvalStatus()));p.setAuditUserId(user);
  replace(p.getRoles(),r.roles(),x->{ProductRole e=new ProductRole();e.setRoleId(id(x.roleId(),"ROL"));e.setProduct(p);e.setRoleType(norm(x.roleType()));e.setMandatory(x.mandatory());return e;});
  replace(p.getBalanceTypes(),r.balanceTypes(),x->{ProductBalanceType e=new ProductBalanceType();e.setBalanceTypeId(id(x.balanceTypeId(),"BAL"));e.setProduct(p);e.setBalanceCode(norm(x.balanceCode()));e.setClassification(norm(x.classification()));return e;});
  replace(p.getTransactionTypes(),r.transactionTypes(),x->{ProductTransactionType e=new ProductTransactionType();e.setTransactionTypeId(id(x.transactionTypeId(),"TXN"));e.setProduct(p);e.setTransactionCode(norm(x.transactionCode()));e.setTransactionName(x.transactionName());e.setDebitCreditIndicator(norm(x.debitCreditIndicator()));return e;});
  replace(p.getFeeRates(),r.feeRates(),x->{ProductFeeRate e=new ProductFeeRate();e.setFeeRateId(id(x.feeRateId(),"FEE"));e.setProduct(p);e.setCategory(category(x.categoryCode()));e.setFeeType(norm(x.feeType()));e.setFeeName(x.feeName());e.setFeeAmount(x.feeAmount());e.setFeePercent(x.feePercent());e.setTriggerEvent(x.triggerEvent());e.setAdditionalRatePercent(x.additionalRatePercent());e.setPenaltyPercent(x.penaltyPercent());e.setEffectiveDate(x.effectiveDate());e.setExpiryDate(x.expiryDate());return e;});
  replace(p.getTermRules(),r.termRules(),x->{ProductTermRule e=new ProductTermRule();e.setTermRuleId(id(x.termRuleId(),"TRM"));e.setProduct(p);e.setDurationUnit(x.durationUnit());e.setMinValue(x.minValue());e.setMaxValue(x.maxValue());e.setDefaultValue(x.defaultValue());return e;});
  replace(p.getBusinessRules(),r.businessRules(),x->{ProductBusinessRule e=new ProductBusinessRule();e.setRuleId(id(x.ruleId(),"RUL"));e.setProduct(p);e.setRuleCode(norm(x.ruleCode()));e.setRuleValue(x.ruleValue());e.setEnabled(x.enabled());e.setDescription(x.description());return e;});
  replace(p.getCommunications(),r.communications(),x->{CustomerCommunication e=new CustomerCommunication();e.setCommunicationId(id(x.communicationId(),"COM"));e.setProduct(p);e.setCategory(category(x.categoryCode()));e.setCommunicationType(norm(x.communicationType()));e.setChannel(norm(x.channel()));e.setFrequency(norm(x.frequency()));e.setTemplateName(x.templateName());e.setActive(x.active());return e;}); products.saveAndFlush(p);
 }
 private CustomerCategory category(String code){return categories.findById(norm(code)).orElseThrow(()->new BadRequestException("Unknown customer category: "+code));}
 private void validate(ProductRequest r){if(r.minTermMonths()>r.maxTermMonths())throw new BadRequestException("minTermMonths cannot exceed maxTermMonths");if(r.minRate().compareTo(r.maxRate())>0)throw new BadRequestException("minRate cannot exceed maxRate");if(r.expiryDate()!=null&&r.expiryDate().isBefore(r.effectiveDate()))throw new BadRequestException("expiryDate cannot precede effectiveDate"); if(r.termRules()!=null)r.termRules().forEach(x->{if(x.minValue()>x.maxValue()||x.defaultValue()<x.minValue()||x.defaultValue()>x.maxValue())throw new BadRequestException("Invalid term rule range/default for "+x.durationUnit());});}
 private static <I,E> void replace(List<E> target,List<I> src,Function<I,E> f){target.clear();if(src!=null)src.stream().map(f).forEach(target::add);} private static String id(String supplied,String prefix){return supplied==null||supplied.isBlank()?prefix+UUID.randomUUID().toString().replace("-","").substring(0,17).toUpperCase():norm(supplied);} private static String norm(String s){return s==null?null:s.trim().toUpperCase(Locale.ROOT);} private static String blank(String s){return s==null||s.isBlank()?null:norm(s);}
}
